// Normaliza e RECUSA o que não dá para enviar.
//
// Um telefone curto não dá erro na UAZAPI: ela entrega a mensagem para OUTRA
// pessoa. Mensagem que sai não se desfaz, então a validação é aqui, antes de
// gastar a chamada.

const entrada = $input.first().json;
// O nó Webhook entrega o corpo em `.body`; o `?? entrada` cobre um teste manual
// em que alguém executa este nó com o JSON solto.
const body = entrada.body ?? entrada;

const telefone = String(body.telefone ?? '').replace(/\D/g, '');
const mensagem = String(body.mensagem ?? '').trim();
const origem = String(body.origem ?? 'hub');

// 55 + DDD (2) + número (8 ou 9).
if (telefone.length < 12 || telefone.length > 13) {
  throw new Error(`telefone inválido: "${body.telefone ?? ''}"`);
}
if (!mensagem) {
  throw new Error('mensagem vazia');
}

// O WhatsApp corta em 4096 caracteres. Cortar aqui, avisando, é melhor do que
// deixar a API cortar em silêncio no meio de um link de anúncio.
const LIMITE = 4000;
const texto = mensagem.length > LIMITE
  ? mensagem.slice(0, LIMITE - 24) + '\n\n…(mensagem cortada)'
  : mensagem;

return [{ json: { telefone, texto, origem } }];
